/**
 * 定义女巫药瓶库存、目标、自救及当前狼刀上下文的工具校验。输入为已清洗用药工具与
 * 可信校验上下文；输出保留原结构化规则结果。预检不消费药瓶，不虚构缺失的救药目标；
 * 状态只读入口已归完整状态槽，付款与真实效果仍在原提交边界。
 */
import { scholarMentorBlocks } from "../scholar_mentor/night_frame";
import { isMagicianBoard, resolveMagicianNightTarget } from "../magician/night_frame";
import { nativePotionsCanCombine } from "./policies";
import { RuleError } from "@ai-werewolf-arena/game-contract";
/** 文件说明：女巫工具校验规则。 */
import { PotionType, Phase, WitchSelfHealRule, StatusMark } from "../../../../core/domain/model";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { StatusMarksComponent } from "../../../../core/domain/components/status_marks";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { ToolRuleMap, isAliveTarget } from "../../validation/contracts";
import { getWitchState } from "./ports";
import { activeNightAbility } from "../abilities";
import { luckyTargetAllowed } from "../night_action_history";

/** 女巫工具校验规则集合。 */
export const WITCH_VALIDATION_RULES: ToolRuleMap = {
  use_potion: ({ world, actorId, role, toolCall, day, abilityId, phase }) => {
    const ability = activeNightAbility(role, "potion", day ?? 1, abilityId);
    const witchState = ability?.state;
    if (!witchState) {
      return { code: RuleError.WitchOnly };
    }
    if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
    if (toolCall.name !== "use_potion") {
      return { code: RuleError.ToolMismatch };
    }
    if (
      ability?.activation === "lucky" &&
      toolCall.args.potion_type === PotionType.None &&
      toolCall.args.target_id !== actorId
    )
      return { code: RuleError.PoisonTarget };
    if (
      ability?.activation === "black_market" &&
      toolCall.args.potion_type === PotionType.None &&
      !isAliveTarget(world, toolCall.args.target_id)
    )
      return { code: RuleError.PoisonTarget };
    if (toolCall.args.potion_type === PotionType.Heal) {
      const canSelfHeal =
        day === undefined
          ? witchState.canSelfHeal
          : witchState.selfHealRule === WitchSelfHealRule.Always ||
            (witchState.selfHealRule === WitchSelfHealRule.FirstNightOnly && day === 1);
      if (!canSelfHeal && toolCall.args.target_id === actorId) {
        return { code: RuleError.SelfHeal };
      }
      if (witchState.heal <= 0 || witchState.healUsedThisNight) {
        return { code: RuleError.HealUnavailable };
      }
      if (witchState.poisonUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      const requestedId = toolCall.args.target_id;
      if (!isAliveTarget(world, requestedId)) return { code: RuleError.HealTarget };
      const mapping = isMagicianBoard(world)
        ? resolveMagicianNightTarget(world, day ?? 0, requestedId)
        : null;
      if (mapping && !mapping.isCurrent()) return { code: RuleError.HealTarget };
      const targetId = mapping?.effectiveId ?? requestedId;
      if (
        !isAliveTarget(world, targetId) ||
        !world.getComponent(targetId, COMPONENT.Role) ||
        !world.getComponent(targetId, COMPONENT.StatusMarks)?.has(StatusMark.WolfKillMark)
      ) {
        return { code: RuleError.HealTarget };
      }
      return null;
    }
    if (toolCall.args.potion_type === PotionType.Poison) {
      if (scholarMentorBlocks(world, day ?? 1, actorId, "poison"))
        return { code: RuleError.ModifierUnavailable };
      if (witchState.poison <= 0 || witchState.poisonUsedThisNight) {
        return { code: RuleError.PoisonUnavailable };
      }
      if (witchState.healUsedThisNight && !nativePotionsCanCombine(ability!)) {
        return { code: RuleError.TwoPotions };
      }
      if (!isAliveTarget(world, toolCall.args.target_id)) {
        return { code: RuleError.PoisonTarget };
      }
      if (
        !luckyTargetAllowed(world, actorId, ability!, day ?? 1, "poison", toolCall.args.target_id)
      )
        return { code: RuleError.LuckyTargetRepeat };
      return null;
    }
    return null;
  },
};

/**
 * 负责 女巫 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
/** 文件说明：女巫角色 profile。 */
import { Camp, PotionType, Role, WitchSelfHealRule } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { getWitchState, setWitchState } from "./ports";
import { WITCH_LLM_REPAIR_PACK } from "./llm_repair";
import { WITCH_NIGHT_STAGES } from "./night_stages";
import { WITCH_TOOL_SPECS, WITCH_STAGE_DIRECTIVES } from "./tool_specs";
import { WITCH_VALIDATION_RULES } from "./validation_rules";
import { z } from "zod";
import {
  WITCH_KNIFE_VISIBILITY_POLICIES,
  WITCH_POTION_POLICIES,
} from "../../../../core/domain/board";

const witchParameters = z.strictObject({
  selfHeal: z.enum(WitchSelfHealRule).default(WitchSelfHealRule.Disabled),
  knifeVisibility: z.enum(WITCH_KNIFE_VISIBILITY_POLICIES).default("awa_with_heal_v1"),
  potionPolicy: z.enum(WITCH_POTION_POLICIES).default("awa_one_native_v1"),
});

/** 女巫角色配置。 */
export const WITCH_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Witch,
    camp: Camp.Good,
    label: roleName("witch"),
    skillBrief: text("zh-CN", "role.witch.brief"),
    goodSide: "god",
  },
  runtime: {
    configuration: {
      schema: witchParameters,
      defaults: {
        selfHeal: WitchSelfHealRule.Disabled,
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
      },
      apply: (config, value) => {
        const parameters = witchParameters.parse(value);
        return {
          ...config,
          witch: {
            canSelfHeal: parameters.selfHeal,
            knifeVisibility: parameters.knifeVisibility,
            potionPolicy: parameters.potionPolicy,
          },
        };
      },
      serialize: (config) =>
        witchParameters.parse({
          selfHeal: config.witch?.canSelfHeal ?? WitchSelfHealRule.Disabled,
          knifeVisibility: config.witch?.knifeVisibility,
          potionPolicy: config.witch?.potionPolicy,
        }),
    },
    init: (roleComp, ctx) => {
      const selfHealRule = ctx.boardConfig?.witch?.canSelfHeal ?? WitchSelfHealRule.Disabled;
      setWitchState(roleComp, {
        heal: 1,
        poison: 1,
        selfHealRule,
        canSelfHeal:
          selfHealRule === WitchSelfHealRule.Always ||
          selfHealRule === WitchSelfHealRule.FirstNightOnly,
        ...(ctx.boardConfig?.witch?.knifeVisibility &&
        ctx.boardConfig.witch.knifeVisibility !== "awa_with_heal_v1"
          ? { knifeVisibility: ctx.boardConfig.witch.knifeVisibility }
          : {}),
        ...(ctx.boardConfig?.witch?.potionPolicy === "awa_both_native_experimental_v1"
          ? { potionPolicy: ctx.boardConfig.witch.potionPolicy }
          : {}),
        healUsedThisNight: false,
        poisonUsedThisNight: false,
      });
    },
    toolSpecs: WITCH_TOOL_SPECS,
    stageDirectives: WITCH_STAGE_DIRECTIVES,
    validationRules: WITCH_VALIDATION_RULES,
    nightStages: WITCH_NIGHT_STAGES,
    llmRepair: WITCH_LLM_REPAIR_PACK,
    baselineAction: (roleComp, request) => {
      if (!request.allowedTools.includes("use_potion")) {
        return null;
      }
      return {
        name: "use_potion",
        args: {
          target_id: request.actorId,
          potion_type: PotionType.None,
        },
      };
    },
  },
  presentation: nativeRolePresentation("witch"),
};

/**
 * 提供女巫普通药剂状态命令的公开入口。输入是原规则检查之后选定的只读状态或能力引用；
 * 输出按原顺序写入夜间标记、药剂库存和回合关闭状态。行动权限与效果提交仍由调用方负责，
 * 失败不会回滚已写标记或已消费资源。独立审计账本和封印的猎魔人原生库存不使用这些命令。
 * 初始化具名绑定保留原输入复制契约，调用方模板不因此获得新的活跃库存写权限。
 */
export {
  getWitchState,
  resetWitchNightState,
  refreshWitchSelfHeal,
  closeWitchPotionTurn,
  consumeWitchHeal,
  consumeWitchPoison,
  consumeRecipientPoison,
} from "./state-slot";

export { setWitchState } from "./state-slot";

export { WITCH_STATE_SLOT } from "./state-slot";
